CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS packages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, category text NOT NULL, description text NOT NULL, price_htg integer NOT NULL CHECK(price_htg >= 0), image text, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), package_id uuid NOT NULL REFERENCES packages(id), occasion text NOT NULL, recipient text NOT NULL, message text NOT NULL DEFAULT '', city text NOT NULL, address text NOT NULL, event_at timestamptz NOT NULL, quantity integer NOT NULL DEFAULT 1 CHECK(quantity BETWEEN 1 AND 1000), unit_price_htg integer NOT NULL, total_htg integer NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','preparing','in_progress','completed','cancelled')), payment_status text NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','pending_verification','paid','refunded')), payment_reference text, live_url text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_user_created ON orders(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS equipment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, stock integer NOT NULL CHECK(stock >= 0), daily_price_htg integer NOT NULL CHECK(daily_price_htg >= 0));
CREATE TABLE IF NOT EXISTS rental_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), equipment_id uuid NOT NULL REFERENCES equipment(id), quantity integer NOT NULL CHECK(quantity > 0), start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, city text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','completed','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(end_at > start_at));
